import{_ as a,o as s,c as n,a2 as o}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"2.5 交流电路基础","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-5-jiao-liu-dian-lu-ji-chu.md","filePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-5-jiao-liu-dian-lu-ji-chu.md","lastUpdated":1793095197000}'),l={name:"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-5-jiao-liu-dian-lu-ji-chu.md"};function i(e,t,r,d,p,h){return s(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="_2-5-交流电路基础" tabindex="-1">2.5 交流电路基础 <a class="header-anchor" href="#_2-5-交流电路基础" aria-label="Permalink to &quot;2.5 交流电路基础&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>到目前为止讲的&quot;水流&quot;都是<strong>直流</strong>——方向不变。但家里和工厂里用的电,是<strong>交流电</strong>,电流方向每秒钟要来回变 50 次。这一节讲清交流电的三大要素、<strong>有效值</strong>怎么算,以及最重要的<strong>三相交流电</strong>和它的两种接法(星形/三角形)。</p><h2 id="一、直流电与交流电的区别" tabindex="-1">一、直流电与交流电的区别 <a class="header-anchor" href="#一、直流电与交流电的区别" aria-label="Permalink to &quot;一、直流电与交流电的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>直流电(DC)</th><th>交流电(AC)</th></tr></thead><tbody><tr><td>电流方向</td><td>始终不变</td><td>周期性改变方向</td></tr><tr><td>大小</td><td>基本不变</td><td>随时间按正弦规律变化</td></tr><tr><td>来源</td><td>电池、直流发电机</td><td>交流发电机</td></tr><tr><td>例子</td><td>干电池、蓄电池</td><td>市电(220 V/380 V)</td></tr></tbody></table><p><strong>交流电的波形</strong>是正弦波,就像起伏的波浪:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  幅值▲</span></span>
<span class="line"><span>   Um │    ╱╲</span></span>
<span class="line"><span>      │   ╱  ╲</span></span>
<span class="line"><span>      │  ╱    ╲      ╱╲</span></span>
<span class="line"><span>   0 ─┼────╲────╲────╱────╲────► t</span></span>
<span class="line"><span>      │     ╲    ╱  ╲╱</span></span>
<span class="line"><span>   -Um│      ╲╱</span></span></code></pre></div><h2 id="二、正弦交流电的三要素" tabindex="-1">二、正弦交流电的三要素 <a class="header-anchor" href="#二、正弦交流电的三要素" aria-label="Permalink to &quot;二、正弦交流电的三要素&quot;">​</a></h2><p>描述正弦交流电,需要三个&quot;要素&quot;:</p><ol><li><strong>幅值(最大值)Um</strong>:波形能达到的最高值;</li><li><strong>频率 f / 周期 T</strong>: <ul><li><strong>周期 T</strong>:完成一次完整变化需要的时间,单位秒(s);</li><li><strong>频率 f</strong>:每秒钟变化的次数,单位<strong>赫兹(Hz)</strong>;</li><li>关系:<code>T = 1/f</code>。我国工频交流电 <strong>f = 50 Hz</strong>,则 <code>T = 1/50 = 0.02 s</code>;</li></ul></li><li><strong>初相位</strong>:起始时刻的角度位置(决定波形从哪开始),做题时一般默认初相位为 0。</li></ol><h2 id="三、有效值-交流电的-等效直流值" tabindex="-1">三、有效值:交流电的&quot;等效直流值&quot; <a class="header-anchor" href="#三、有效值-交流电的-等效直流值" aria-label="Permalink to &quot;三、有效值:交流电的&quot;等效直流值&quot;&quot;">​</a></h2><p>交流电大小一直在变,那&quot;220 V&quot;到底是多少?——<strong>有效值</strong>!</p><p><strong>有效值</strong>:交流电通过电阻时,一个周期内产生的热量,与某个<strong>大小不变的直流电</strong>在同样时间内产生的热量相等,那么这个直流电的数值就是该交流电的<strong>有效值</strong>。</p><ul><li>正弦交流电:<strong>有效值 = 最大值 / √2 ≈ 0.707 × 最大值</strong><ul><li><code>U = Um / √2</code>,<code>I = Im / √2</code></li></ul></li><li>反过来:<strong>最大值 = √2 × 有效值 ≈ 1.414 × 有效值</strong><ul><li>市电有效值 220 V → 最大值 <code>Um = 220 × 1.414 ≈ 311 V</code></li><li>380 V 线电压 → 最大值 ≈ 537 V</li></ul></li></ul><blockquote><p>⚠️ 常考:我们说的&quot;220 V&quot;&quot;380 V&quot;都是<strong>有效值</strong>,不是最大值;设备铭牌上标的也是有效值。</p></blockquote><h2 id="四、三相交流电" tabindex="-1">四、三相交流电 <a class="header-anchor" href="#四、三相交流电" aria-label="Permalink to &quot;四、三相交流电&quot;">​</a></h2><h3 id="_1-什么是三相交流电" tabindex="-1">1. 什么是三相交流电 <a class="header-anchor" href="#_1-什么是三相交流电" aria-label="Permalink to &quot;1. 什么是三相交流电&quot;">​</a></h3><p>发电机发出三组交流电,它们在时间上<strong>相差 120°</strong>(1/3 个周期),组成三相交流电。每一&quot;相&quot;用 L1、L2、L3 表示(也写作 A、B、C 相)。</p><p><strong>为什么用三相?</strong> 三相电功率大、效率高,还能产生<strong>旋转磁场</strong>(这正是电动机能转起来的根本原因,第 8 章详讲)。</p><h3 id="_2-两个关键概念-相电压与线电压" tabindex="-1">2. 两个关键概念:相电压与线电压 <a class="header-anchor" href="#_2-两个关键概念-相电压与线电压" aria-label="Permalink to &quot;2. 两个关键概念:相电压与线电压&quot;">​</a></h3><ul><li><strong>相电压</strong>:每相绕组两端的电压(即&quot;火线&quot;与&quot;零线/中性线&quot;之间的电压);</li><li><strong>线电压</strong>:任意两根火线之间的电压。</li></ul><h3 id="_3-星形-y-接法与三角形-δ-接法" tabindex="-1">3. 星形(Y)接法与三角形(Δ)接法 <a class="header-anchor" href="#_3-星形-y-接法与三角形-δ-接法" aria-label="Permalink to &quot;3. 星形(Y)接法与三角形(Δ)接法&quot;">​</a></h3><p><strong>星形接法(Y)</strong>:三组线圈的末端连在一起(称中性点),首端引出三根火线。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        L1(火线)</span></span>
<span class="line"><span>    ┌───┐</span></span>
<span class="line"><span>  ｜线圈1｜●────┐</span></span>
<span class="line"><span>    └───┘      ├─ 中性点(N/零线)</span></span>
<span class="line"><span>  ｜线圈2｜●────┘</span></span>
<span class="line"><span>  ｜线圈3｜●───────► 实际是三条线圈接法示意</span></span></code></pre></div><p><strong>关键关系(星形)</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>线电压 U线 = √3 × 相电压 U相  (√3 ≈ 1.732)</span></span>
<span class="line"><span>线电流 I线 = 相电流 I相</span></span></code></pre></div><p>我们日常:相电压 220 V,线电压 380 V(<code>220 × √3 ≈ 380</code>)。</p><p><strong>三角形接法(Δ)</strong>:首尾相接成闭合三角形,没有中性点。</p><p><strong>关键关系(三角形)</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>线电压 U线 = 相电压 U相</span></span>
<span class="line"><span>线电流 I线 = √3 × 相电流 I相</span></span></code></pre></div><blockquote><p>💡 记忆口诀:<strong>&quot;Y 形升电压、Δ 形升电流&quot;</strong>——星形接法线电压是相电压的 √3 倍;三角形接法线电流是相电流的 √3 倍。</p></blockquote><h3 id="_4-三相四线制与三相五线制" tabindex="-1">4. 三相四线制与三相五线制 <a class="header-anchor" href="#_4-三相四线制与三相五线制" aria-label="Permalink to &quot;4. 三相四线制与三相五线制&quot;">​</a></h3><ul><li><strong>三相四线制</strong>:三根火线 + 一根零线(中性线),用于 220/380 V 供电;</li><li><strong>三相五线制</strong>:三根火线 + 零线 + 保护接地线(PE),即 TN-S 系统(第 9 章详讲)。</li></ul><h2 id="五、交流电路里的三种-阻碍-简要了解" tabindex="-1">五、交流电路里的三种&quot;阻碍&quot;(简要了解) <a class="header-anchor" href="#五、交流电路里的三种-阻碍-简要了解" aria-label="Permalink to &quot;五、交流电路里的三种&quot;阻碍&quot;(简要了解)&quot;">​</a></h2><p>交流电通过不同元件时,受到的阻碍不完全相同:</p><table tabindex="0"><thead><tr><th>元件</th><th>阻碍类型</th><th>特点</th></tr></thead><tbody><tr><td>电阻 R</td><td>电阻</td><td>阻碍与频率无关</td></tr><tr><td>电感 L</td><td>感抗 XL</td><td>频率越高阻碍越大(阻止电流突变)</td></tr><tr><td>电容 C</td><td>容抗 XC</td><td>频率越高阻碍越小(允许电流变化)</td></tr></tbody></table><blockquote><p>💡 这一部分记住&quot;<strong>电感通直流阻交流、电容通交流阻直流</strong>&quot;即可,深层次内容(功率因数、无功功率)在考证里不深究。</p></blockquote><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 我国工频交流电频率 <strong>50 Hz</strong>,周期 0.02 s。</li><li>✅ 220 V、380 V 均为<strong>有效值</strong>;最大值 = 有效值 × √2 ≈ 1.414 倍。</li><li>✅ 星形接法:线电压 = √3 × 相电压(220 → 380);三角形接法:线电流 = √3 × 相电流。</li><li>✅ 电感&quot;通直流阻交流&quot;,电容&quot;通交流阻直流&quot;。</li><li>⚠️ 易混点:√3(≈1.732)与 √2(≈1.414)别搞混——√3 是相线电压关系,√2 是有效值/最大值关系。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>交流电方向、大小随时间正弦变化,由幅值、频率、初相位三要素描述。</li><li>有效值 = 最大值/√2;市电 220 V 是有效值,最大值约 311 V。</li><li>三相交流:星形接法线电压 = √3×相电压,三角形接法线电流 = √3×相电流。</li><li>我国工频 50 Hz,周期 0.02 s。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(单选)我国低压交流电的频率是()。 A. 50 Hz　B. 60 Hz　C. 100 Hz　D. 25 Hz</li><li>(判断)我们常说的市电 220 V 是指交流电的最大值。( )</li><li>(单选)正弦交流电的有效值约为最大值的()倍。 A. 0.5　B. 0.707　C. 1.414　D. 1.732</li><li>(单选)星形接法时,线电压与相电压的关系是()。 A. 相等　B. 线电压=√3×相电压　C. 相电压=√3×线电压　D. 无固定关系</li><li>(判断)三相交流电三相之间的相位差为 120°。( )</li><li>(单选)交流电一个周期的频率为 50 Hz 时,周期是()。 A. 0.01 s　B. 0.02 s　C. 0.2 s　D. 2 s</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>A</strong>。我国工频交流电为 50 Hz。</li><li><strong>×</strong>。220 V 是有效值;交流电最大值 = 220×√2 ≈ 311 V。</li><li><strong>B</strong>。有效值 = 最大值/√2 ≈ 0.707 × 最大值。</li><li><strong>B</strong>。星形接法线电压 = √3 × 相电压(如 380 = √3 × 220)。</li><li><strong>√</strong>。三相之间相位差 120°。</li><li><strong>B</strong>。T = 1/f = 1/50 = 0.02 s。</li></ol></details>`,44)])])}const g=a(l,[["render",i]]);export{u as __pageData,g as default};
